#pragma once

// GpuTileSource — terrain tiles generated by the GPU synthesis pass, behind
// the terrain module's TileGenerator interface (ROADMAP R10.2).
//
// generate() queues a TerrainSynthPass job and returns a future for the
// tile's CPU Heightmap; add_to_graph() (driven by TerrainPass::add_to_graph,
// once per frame) records the synthesis and fulfils futures as readbacks
// land. A delivered Heightmap carries gpu_tile = its image's id: the image
// the GPU wrote is parked here until TerrainPass::set_tile adopts it (no
// re-upload of the heights), or expires unclaimed (a streamed tile the
// camera outran). Physics and navmesh consume the read-back heights, so they
// always match what is rendered.
//
// Fallbacks keep the CPU generator in charge of correctness: params the GPU
// cannot do (droplet erosion, oversized tiles) are refused by supports(),
// and a job that fails on the GPU (out of memory) is regenerated on a CPU
// worker and delivered through the same future.

#include <cstdint>
#include <expected>
#include <future>
#include <map>
#include <memory>
#include <optional>
#include <string>
#include <vector>

#include "engine/core/error.hpp"
#include "engine/renderer/terrain_synth_pass.hpp"
#include "engine/rhi/gpu_allocator.hpp"
#include "engine/rhi/render_graph.hpp"
#include "engine/terrain/tile_generator.hpp"

namespace engine::rhi {
class Device;
class PipelineCache;
}

namespace engine::renderer {

class GpuTileSource final : public terrain::TileGenerator {
public:
    // Frames a delivered tile image waits to be adopted before it is freed.
    static constexpr int unclaimed_frames = 240;

    [[nodiscard]] static std::expected<std::unique_ptr<GpuTileSource>, core::Error>
    create(const rhi::Device& device, rhi::GpuAllocator& allocator, rhi::PipelineCache& cache,
           const std::string& cooked_shader_dir);

    // Pending futures receive an empty (invalid) Heightmap. The device must
    // be idle (GPU work referencing the jobs has finished).
    ~GpuTileSource() override;

    [[nodiscard]] bool supports(const terrain::TerrainParams& params) const override;
    [[nodiscard]] std::future<terrain::Heightmap>
    generate(const terrain::TerrainParams& params) override;

    // Records this frame's synthesis work, delivers finished tiles to their
    // futures and ages unclaimed images. Call once per frame.
    void add_to_graph(rhi::RenderGraph& graph);

    // Hands over the image of a delivered tile (R32F metres,
    // SHADER_READ_ONLY_OPTIMAL); nullopt when unknown or expired.
    [[nodiscard]] std::optional<rhi::GpuImage> take_image(std::uint64_t gpu_tile);

    // Tiles queued or in flight (their futures are not ready yet).
    [[nodiscard]] bool busy() const { return !pending_.empty(); }

private:
    // Passkey: only create() can name Key, so construction goes through it.
    struct Key {
        explicit Key() = default;
    };

public:
    explicit GpuTileSource(Key /*key*/) {}

private:
    void deliver(TerrainSynthPass::Result result);
    void fall_back_to_cpu(std::uint64_t id);

    struct Pending {
        std::promise<terrain::Heightmap> promise;
        terrain::TerrainParams           params;
    };
    struct Parked {
        rhi::GpuImage image;
        int           frames_left = unclaimed_frames;
    };

    TerrainSynthPass                 synth_;
    std::map<std::uint64_t, Pending> pending_; // by job id
    std::map<std::uint64_t, Parked>  parked_;  // delivered, awaiting adoption
    std::vector<std::future<void>>   cpu_fallbacks_;
};

} // namespace engine::renderer
